colors=[9,6,3,4]
holes={9:[[1,0,1],[1,1,1],[0,1,0]],6:[[0,1,1],[0,1,1],[1,0,0]],3:[[1,0,1],[0,1,1],[0,1,0]],4:[[1,1,1],[0,1,0],[0,1,0]]}
out=[[2]*7]
for idx,c in enumerate(colors):
    for i in range(5):
        row=[2]+[c]*5+[2]
        if 1<=i<=3:
            for j in range(1,4):
                if holes[c][i-1][j-1]: row[j+1]=2
        out.append(row)
    out.append([2]*7)
print(len(out),[len(r) for r in out],out)
print('\n'.join(' '.join(map(str,r)) for r in out))

# Construct the panel crop while preserving the 2x2 panel layout.
bg=2
masks={9:[[1,0,1],[1,1,1],[0,1,0]],6:[[0,1,1],[0,1,1],[1,0,0]],3:[[1,0,1],[0,1,1],[0,1,0]],4:[[1,1,1],[0,1,0],[0,1,0]]}
def tile(c):
    a=[[c]*5 for _ in range(5)]
    for r in range(3):
        for q in range(3):
            if masks[c][r][q]: a[r+1][q+1]=bg
    return a
panels=[[9,6],[3,4]]
grid=[[bg]*13]
for pr,rowcolors in enumerate(panels):
    ts=[tile(c) for c in rowcolors]
    for r in range(5):
        grid.append([bg]+ts[0][r]+[bg]+ts[1][r]+[bg])
    grid.append([bg]*13)
print(len(grid), [len(r) for r in grid])
print('\n'.join(' '.join(map(str,r)) for r in grid))
